  <!-- TARGET AUDIENCE & PREREQUISITES SECTION -->\r\n    <section class=\"container course-body-section\" id=\"audience-section\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">ELIGIBILITY & AUDIENCE</span>\r\n        <h2 class=\"section-title\">Who Is This Program <span class=\"gradient-text\">Built For?</span></h2>\r\n      </div>\r\n\r\n      <div id=\"audience-container\" style=\"max-width:860px;\">\n        <div class=\"audience-grid\">\n        <div class=\"audience-card best-for\">\n          <h3><span style=\"color:var(--green)\">✓</span> Ideal For (Best For)</h3>\n          <ul class=\"audience-list\">\n            <li><span class=\"bullet-icon\">✓</span><span>Aspiring digital marketing professionals.</span></li><li><span class=\"bullet-icon\">✓</span><span>Entrepreneurs wanting to scale their businesses online.</span></li><li><span class=\"bullet-icon\">✓</span><span>Freelancers looking to offer high-demand digital services.</span></li>\n          </ul>\n        </div>\n        \n          <div class=\"audience-card not-for\">\n            <h3><span style=\"color:var(--orange)\">✕</span> Who Is This NOT For</h3>\n            <ul class=\"audience-list\">\n              <li><span class=\"bullet-icon\">✕</span><span>Those looking for passive, theoretical lectures without hands-on implementation.</span></li><li><span class=\"bullet-icon\">✕</span><span>Students expecting get-rich-quick schemes.</span></li>\n            </ul>\n          </div>\n        \n      </div>\n      </div>\r\n\r\n      <div id=\"prerequisites-container\" style=\"max-width:860px;\">\n        <div class=\"prerequisites-box\">\n        <div class=\"prereq-item\">\n          <h4>Required Prerequisites</h4>\n          <p>Basic computer and internet literacy</p>\n        </div>\n        <div class=\"prereq-item\">\n          <h4>Recommended Background</h4>\n          <p>Familiarity with social media platforms</p>\n        </div>\n      </div>\n      </div>\r\n    </section>\r\n\r\n    <!-- LEARNING OUTCOMES SECTION -->\r\n    <section class=\"container course-body-section\" id=\"outcomes-section\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">LEARNING OUTCOMES</span>\r\n        <h2 class=\"section-title\">Action-Oriented <span class=\"gradient-text\">Competencies You Gain</span></h2>\r\n      </div>\r\n\r\n      <div id=\"outcomes-container\" style=\"max-width:860px;\">\n        <div class=\"outcomes-grid\">\n        \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">STRATEGIZE</span>\n              <p class=\"outcome-text\">Develop comprehensive marketing plans based on business goals.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">EXECUTE</span>\n              <p class=\"outcome-text\">Launch and manage campaigns across relevant digital channels.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">MEASURE</span>\n              <p class=\"outcome-text\">Implement tracking and reporting to accurately attribute conversions.</p>\n            </div>\n          \n            <div class=\"outcome-item\">\n              <span class=\"outcome-verb-badge\">OPTIMIZE</span>\n              <p class=\"outcome-text\">Improve campaign performance continuously using A/B testing and analytics.</p>\n            </div>\n          \n      </div>\n      </div>\r\n    </section>\r\n\r\n    <!-- LEARNING JOURNEY ROADMAP SECTION (TEMPLATE C) -->\r\n    <section class=\"container course-body-section\" id=\"journey-section\" style=\"display:none;\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">CURRICULUM ARCHITECTURE</span>\r\n        <h2 class=\"section-title\">Multi-Stage <span class=\"gradient-text\">Learning Journey</span></h2>\r\n      </div>\r\n\r\n      <div id=\"journey-container\" style=\"max-width:860px;\">\r\n        <!-- Populated by JS -->\r\n      </div>\r\n    </section>\r\n\r\n    <!-- CURRICULUM SECTION -->\r\n    <section class=\"container course-body-section\" id=\"curriculum-section\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">STEP-BY-STEP MODULES</span>\r\n        <h2 class=\"section-title\">Detailed <span class=\"gradient-text\">Curriculum & Labs</span></h2>\r\n      </div>\r\n\r\n      <div class=\"curriculum-modules\" id=\"curriculum-container\" style=\"max-width:860px;\">\n        <div class=\"curriculum-module open\">\n        <div class=\"curriculum-module-header\" role=\"button\" tabindex=\"0\" aria-expanded=\"true\">\n          <span class=\"module-label\">Module 01</span>\n          <span class=\"module-title\">GBP Optimization</span>\n          <span class=\"module-lessons-count\">3 Lessons</span>\n          <span class=\"module-chevron\">⌄</span>\n        </div>\n        <div class=\"curriculum-module-body\">\n          <div class=\"module-purpose-box\">\n            <strong>Module Focus:</strong> Develop practical competence in GBP Optimization.\n            \n              <ul style=\"margin: 8px 0 0 18px; padding: 0; list-style-type: disc; font-size: 0.88rem; line-height: 1.5; color: var(--text-secondary);\">\n                <li>Understand core mechanics of GBP Optimization.</li><li>Apply tools effectively for GBP Optimization.</li><li>Troubleshoot common issues in this domain.</li>\n              </ul>\n            \n            \n              <div style=\"margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center;\">\n                <span style=\"font-size: 0.78rem; font-weight: 700; color: var(--navy);\">Key Concepts:</span>\n                <span style=\"background: rgba(5, 153, 168, 0.08); color: var(--teal); border: 1px solid rgba(5, 153, 168, 0.2); font-size: 0.75rem; font-weight: 600; padding: 2px 8px; border-radius: var(--radius-full);\">Concept related to GBP Optimization</span><span style=\"background: rgba(5, 153, 168, 0.08); color: var(--teal); border: 1px solid rgba(5, 153, 168, 0.2); font-size: 0.75rem; font-weight: 600; padding: 2px 8px; border-radius: var(--radius-full);\">Best Practices</span><span style=\"background: rgba(5, 153, 168, 0.08); color: var(--teal); border: 1px solid rgba(5, 153, 168, 0.2); font-size: 0.75rem; font-weight: 600; padding: 2px 8px; border-radius: var(--radius-full);\">Optimization</span>\n              </div>\n            \n          </div>\n\n          <div class=\"lessons-timeline\">\n            \n              <div class=\"lesson-card\">\n                <div class=\"lesson-card-header\">\n                  <span class=\"lesson-num-badge\">1.1</span>\n                  <span class=\"lesson-title-text\">Claiming &amp; Verifying GBP</span>\n                </div>\n                <div class=\"lesson-meta-grid\">\n                  <div class=\"lesson-meta-item\">\n                    <strong>Taught:</strong> Step-by-step breakdown of Claiming &amp; Verifying GBP.\n                    \n                  </div>\n                  <div class=\"lesson-meta-item\"><strong>Learner Lab:</strong> Completes a targeted exercise focused on Claiming &amp; Verifying GBP.</div>\n                  <div class=\"lesson-meta-item\"><strong>Why It Matters:</strong> Essential for mastering the broader GBP Optimization strategy.</div>\n                  <div class=\"lesson-meta-item\"><strong>Expected Deliverable:</strong> A tangible asset or configuration related to the lesson.</div>\n                  \n                </div>\n              </div>\n            \n              <div class=\"lesson-card\">\n                <div class=\"lesson-card-header\">\n                  <span class=\"lesson-num-badge\">1.2</span>\n                  <span class=\"lesson-title-text\">Profile Optimization</span>\n                </div>\n                <div class=\"lesson-meta-grid\">\n                  <div class=\"lesson-meta-item\">\n                    <strong>Taught:</strong> Step-by-step breakdown of Profile Optimization.\n                    \n                  </div>\n                  <div class=\"lesson-meta-item\"><strong>Learner Lab:</strong> Completes a targeted exercise focused on Profile Optimization.</div>\n                  <div class=\"lesson-meta-item\"><strong>Why It Matters:</strong> Essential for mastering the broader GBP Optimization strategy.</div>\n                  <div class=\"lesson-meta-item\"><strong>Expected Deliverable:</strong> A tangible asset or configuration related to the lesson.</div>\n                  \n                </div>\n              </div>\n            \n              <div class=\"lesson-card\">\n                <div class=\"lesson-card-header\">\n                  <span class=\"lesson-num-badge\">1.3</span>\n                  <span class=\"lesson-title-text\">Managing Reviews</span>\n                </div>\n                <div class=\"lesson-meta-grid\">\n                  <div class=\"lesson-meta-item\">\n                    <strong>Taught:</strong> Step-by-step breakdown of Managing Reviews.\n                    \n                  </div>\n                  <div class=\"lesson-meta-item\"><strong>Learner Lab:</strong> Completes a targeted exercise focused on Managing Reviews.</div>\n                  <div class=\"lesson-meta-item\"><strong>Why It Matters:</strong> Essential for mastering the broader GBP Optimization strategy.</div>\n                  <div class=\"lesson-meta-item\"><strong>Expected Deliverable:</strong> A tangible asset or configuration related to the lesson.</div>\n                  \n                </div>\n              </div>\n            \n          </div>\n\n          <div class=\"module-footer-meta\"